/* PowerGood ADC (PA0=ADC_IN0) + status LED (PC13)
   Divider R110 10k / R111 3.3k (ratio 3.3/13.3 = 0.24812): 9V in -> 2.23V.
   Warning window: 8.0~12.0V. It encloses the 8.4~11.5V operating range, so the LED does not
   flash inside that range.
   V_DDA is estimated from the VREFINT calibration value to compute the divider voltage [mV];
   PC13 is lit inside the window and blinks at a 0.4s period (50% duty) outside it.
   At 12.0V the divider gives 2.977V, about 0.3V below VDDA (3.28V measured), so the ADC does not saturate. */
#define PGOOD_DIV_LO_MV     1985U  /* Divider voltage for 8.0V (8.0 * 0.24812) */
#define PGOOD_DIV_HI_MV     2977U  /* Divider voltage for 12.0V (12.0 * 0.24812) */
#define PGOOD_POLL_MS       100U   /* ADC sampling interval */
#define PGOOD_BLINK_MS      200U   /* PC13 blink half-period (0.4s period, 50% duty) */
#define ADC_FULL_SCALE      4095U  /* 12bit */
/* VREFINT factory calibration value (taken at VDDA=3.3V). Guarded because bare HAL projects sometimes leave it undefined */
#ifndef VREFINT_CAL_ADDR
#define VREFINT_CAL_ADDR    ((uint16_t *)0x1FFFF7BAU)
#endif
#ifndef VREFINT_CAL_VREF
#define VREFINT_CAL_VREF    3300U    /* mV */
#endif

/* ---- VCP debug console (USART2 PA2/PA3, 115200bps, STLINK-V3 VCP) ---- */
#define DBG_LINE_MAX  64   /* RX line buffer; ample for the longest command ("MSEND"/"MRECV" plus 11 bytes) */
#define DBG_TX_MAX    320  /* TX formatting buffer (a snapshot is ~250 chars, plus the three override fields) */

/* ---- PA8 (Effect) falling-edge delay - pop noise countermeasure ----
   On Effect -> Bypass, PA9 (B-OUT) goes High immediately, but only the PA8 (Effect)
   falling edge is delayed by EFFECT_OFF_DELAY_US. The point is to widen the handover
   overlap between Q8 (bypass side) turning on and Q15 (effect side) turning off
   from 0.6ms to 6.4ms, matching the overlap of the Bypass -> Effect direction.
   Do NOT apply this to the rising edge (Bypass -> Effect): that would shrink the B->E
   overlap from 6.4ms to 0.6ms, making it as hard a splice as E->B, which defeats the purpose.
   Timing uses TIM14 as a 1MHz one-shot (1 count = 1us, max 65.535ms). */
#define EFFECT_OFF_DELAY_US  5800u  /* Default 5.8ms; changeable at runtime with the VCP console EDLY command */
#define EFFECT_OFF_DELAY_MAX 60000u /* Upper bound that still fits the 16-bit TIM14 ARR */

/* MIDI monitor: ring buffer holding USART1 RX/TX bytes tagged with a direction flag.
   Drained by the VCP M command. The size must be a power of two */
#define MIDI_MON_SIZE     128u
#define MIDI_MON_DIR_OUT  0x100u  /* Entry bit8: 0=IN (received), 1=OUT (transmitted) */
#define MIDI_MON_MAX_PER_RESP  40u  /* Max entries per M command (keeps the reply within DBG_TX_MAX) */
